We didn't like how long the breadcrumb trail was getting, so I was tasked to making it shorter: it was decided that for course pages we should include a link back to the course and the link to the last clickable crumb, if any. We have not touched breadcrumbs on other pages as we were mostly concerned with course pages. Here's my code: (excerpted from /theme/essential/renderers.php) 
```text
     /*
     * This renders the navbar.
     * Uses bootstrap compatible html.
     */
    public function navbar() {
        $is_course = false;
        $items = $this->page->navbar->get_items();

        //If this is a course, only output the course node and the last link node (if any)
        //       (e.g. $item->action is not null)
        foreach ($items as $item) {
                if (!$is_course) {
                        $is_course = (navigation_node::TYPE_COURSE == $item->type);
                }
        }

        if ($is_course) {
                //Only output some nodes
                $last_node_found = false;
                $items = array_reverse($items);

                foreach ($items as $item) {
                        //Only output crumbs with links
                        if (navigation_node::TYPE_COURSE == $item->type ||
                                (!$last_node_found && $item->action)) {
                                $last_node_found = true;
                                $item->hideicon = true;
                                $breadcrumbs[] = $this->render($item);
                        }

                        if (navigation_node::TYPE_COURSE == $item->type) {
                                //We're done here
                                break;
                        }
                }

                $breadcrumbs = array_reverse($breadcrumbs);
        }
        else {
                //Output all navigation nodes
                foreach ($items as $item) {
                        $item->hideicon = true;
                        $breadcrumbs[] = $this->render($item);
                }
        }
        $divider = '<span class="divider">/</span>';
        $list_items = '<li>'.join(" $divider</li><li>", $breadcrumbs).'</li>';
        $title = '<span class="accesshide">'.get_string('pagepath').'</span>';
        return $title . "<ul class=\"breadcrumb\">$list_items</ul>";
    }
```
