This is by design. Header and static form elements do not support adding custom attributes by default. This can be remedied. Here is the process: 
```text
// Create your custom form class, set the class attribute as you want using setAttributes.
require_once ($CFG->libdir.'/formslib.php');
class testform extends moodleform {
    protected function definition() {
        $mform = $this->_form;

        /* @var MoodleQuickForm_header $header */
        $header = $mform->addElement('header', 'aaa', 'bbb');
        $header->setAttributes(array('class' => 'aa'));

        /* @var MoodleQuickForm_text $text */
        $text = $mform->addElement('text', 'yeah', 'oh yeah', array('class' => 'aa'));
        $this->add_action_buttons();
    }
}

// Declare your override form renderer.
class extrarenderer extends MoodleQuickForm_Renderer {

    public function extrarenderer (){
        parent::MoodleQuickForm_Renderer();
        // Override the default fieldset template  by adding your own placeholder - myextraclasses.
        $this->_openFieldsetTemplate = str_replace('{classes}',
                                                   '{classes} {myextraclasses}',
                                                   $this->_openFieldsetTemplate);
    }

    public function renderHeader(&$header) {
        // Render the header.
        parent::renderHeader($header);
        // Replace your placeholder with any class if set.
        $myextraclasses = $header->getAttribute('class');
        if (empty($myextraclasses)) {
            $myextraclasses = '';
        }

        $this->_html = str_replace('{myextraclasses}', $myextraclasses, $this->_html);
    }
}

// Finally set the renderer in place
$GLOBALS['_HTML_QuickForm_default_renderer'] = new extrarenderer();

// And now you can do the rest.
$form = new testform();
// Any processing

echo $OUTPUT->header();

$form->display();

echo $OUTPUT->footer();
```
 And than you can work from here, change anything else etc.

